  ('Plage Le Rocher', 'plage-le-rocher-osm1312956959', '2B', 'Corse', 8.805975, 42.600342, 'plage'),
  ('Calanca di a Torre', 'calanca-di-a-torre-osm1427198445', '2B', 'Corse', 9.323181, 42.715101, 'plage')
) as c(name, slug, department, region, lng, lat, structure)
